(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x + w1x, my = y + w1y;
  const w2x = Math.sin(my*0.03-t*0.5)*8 + Math.cos(mx*0.025+t*0.4)*6;
  const w2y = Math.cos(mx*0.028+t*0.45)*8 + Math.sin(my*0.022-t*0.55)*6;
  const sx = mx + w2x, sy = my + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.5],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.0],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,2.0],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,2.5],
    [80+Math.sin(t*0.7+3)*60,40+Math.cos(t*0.3+1)*40,0.11,2.1,3.0],
    [400+Math.cos(t*0.45+2)*70,220+Math.sin(t*0.65+4)*50,0.05,1.8,3.5]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph*0.5);
    hS+=Math.sin(d*f*1.3-t*sp*0.8+ph*0.3+2.0);
  }
  const act=aS/8,inh=iS/8,harm=hS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+(Math.sin(sx*0.08-sy*0.06+t*1.5)+Math.cos(sx*0.07+sy*0.09-t*1.3))*0.2+(Math.sin((sx+sy)*0.12+t*2.5)+Math.sin((sx-sy)*0.1-t*2))*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.08-ang*2+t*0.9)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+harm*0.2)*2.2);
  const reaction2=Math.tanh((harm*0.8-act*0.5+Math.sin(dist*0.08-ang*2+t*0.9)*1.5)*1.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend=reaction*0.55+reaction2*0.2+cell*0.25,v=blend*0.5+0.5;
  const pal=[[6,22,58],[10,55,88],[18,110,122],[32,162,148],[95,185,115],[220,195,60],[218,138,48],[185,72,55],[120,38,68],[55,24,78],[6,22,58]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.15:Math.abs(reaction2)>0.6?1.08:1.0;
  const vD=Math.sqrt((x-cx)**2+(y-cy)**2),vig=1.0-Math.pow(vD/280,2)*0.3;
